import { publishModelVersion } from '@projexlight/sdk-lead-scoring';
await publishModelVersion({
  tenant_id, model_id: 'mql-v2', version: '2.0.0',
  weights: [
    { feature: 'company_size_employees', weight: 0.30 },
    { feature: 'industry_match', weight: 0.25 },
    { feature: 'site_visits_30d', weight: 0.20 },
    { feature: 'demo_attended', weight: 0.25 },
  ],
  activate: true,
});

subscribeEvents('engagement.encounter.completed.v1', async (e) => {
  if (e.payload.kind !== 'demo') return;
  await scoreLead({ tenant_id: e.tenant_id, lead_id: e.payload.contact_id });
});

import { scoreBulk } from '@projexlight/sdk-lead-scoring';
const { job_id } = await scoreBulk({
  tenant_id, model_id: 'mql-v2',
  filter: { stage: 'open' },
});

import { explainScore } from '@projexlight/sdk-lead-scoring';
const exp = await explainScore({
  lead_id, at: '2026-05-15T12:00Z',
});
// exp = { score: 87, model_version: 'mql-v2', contributing: [{ feature: 'demo_attended', value: true, weight: 0.25, contribution: 0.25 }, ...] }
